.ac-box { display: flex; justify-content: center; align-items: center; height: calc(100vw / 16 * 9); margin: 0; }
.ac-mod { width: 60%; height: 80%; background-color: #fff; border-radius: 10px; box-shadow: 20px 20px 10px 0px rgba(0, 0, 0, 0.5); overflow: hidden; }
.mod-head { display: flex; justify-content: space-between; align-items: center; background-color: #282727; color: #fff; padding: 10px 15px; border-bottom: 0; height: 10%; }
