.mod-content { display: flex; gap: 10px; height: 90%; }
.AcCloseBtn { transform: scale(1); transition: transform .1s; height: 100%; aspect-ratio: 1 / 1; }
.AcCloseBtn:hover { color: #ff6347; transform: scale(1.2); }

.AcContentSidebar { width: 27%; background-color: #FF00B3; color: #000; float: left; height: 100%; overflow: hidden; }
.AcContentSidebar ul { list-style-type: none; padding: 0; margin: 0; font-weight: bold; overflow-y: auto; height: 100%; box-sizing: border-box; }
