.AcContentSidebar li { padding: 8px 5.56%; position: relative; cursor: pointer; }
.AcContentSidebar li::after { content: ''; position: absolute; bottom: 0; left: 50%; transform: translateX(-50%); width: 88.8889%; height: 1px; background: #D7B8C6; }

.AcMainContent { width: 73%; padding: 10px; float: right; height: 100%; box-sizing: border-box; }
.AcMainContent img { width: 100%; height: auto; margin-bottom: 10px; }
.AcMainContent p { margin: 5px 0; }
.AcMainContent .AcContent-item { display: none; height: 100%; overflow: auto; }
.AcMainContent .AcContent-item:first-child { display: block; }
.AcContentSidebar li:hover, .AcContentSidebar li.active { background-color: #fff; }
.fontGd{ color: #FFBB1C; } .fontGn{ color: #6BFF2B; } .fontP{ color: #B91DFF; } .fontB{ color: #2C8AFF; }
