.Act-box-shyh{
    position: relative;
    width: 100%;
    aspect-ratio: 16 / 9;
    border: 1px solid black;
    border-radius: 10px;
    margin: auto;
    overflow: hidden;
}
.Hero-img {
    position: absolute;
    width: 57.5%;
}
.Title-img {
    position: absolute;
    left: 4.479167%;
    top: 59.259259%;
    width: 39.583%;
}
.Act-window {
    position: absolute;
    left: 44.0625%;
    top: 10.6481481%;
    width: 52.65625%;
    aspect-ratio: 1101 / 862;
    background: #FFFFFF;
    padding: 10px;
    border-radius: 5.722%;
}
.Act-windowhead {
    display: flex;
    position: relative;
    top: 0;
    left: 0;
    bottom: 91%;
    right: 12%;
    width: 100%;
    height: 9.39675%;
    background-color: #0000;
    border-radius: 100px;
    font-size: 170%;
    font-weight: bold;
    align-items: center;
    justify-content: space-evenly;
}
#H1 {
    display: inline-block;
    position: relative;
    color: #A2EFFF;
    z-index: 2;
}
#H0 {
    position: absolute;
    left: 0;
    top: 0;
    z-index: -1;
    -webkit-user-select: none;
    user-select: none;
    -webkit-text-stroke: 0.2em #000;
}
div#H2 {
    background: linear-gradient(90deg, #EE95CA,#EA5F8E);
    padding: 0.2em 1em;
    border-radius: 70px / 100px;
    color: #fff;
    font-size: 65%;
}
div#H3 {
    color: #fff;
    font-size: 100%;
    -webkit-text-stroke: 0.04em #000;
}

.Act-list {
    display: flex;
    flex-direction: column;
    height: 100%;
    padding: 10px;
    gap: 10px;
    overflow: auto;
}
.Act-list2 {
    display: grid;
    grid-template-columns: 6fr 1fr;
    grid-template-rows: 1fr;
    grid-template-areas: "A2 A3";
    gap: 0;
    width: 100%;
    height: 100%;
    align-items: center;
    justify-items: center;
}
.Act-list2 > div:first-child {
    display: grid;
    grid-template-columns: 1fr 4fr 2fr;
    grid-template-rows: 1fr 1fr;
    grid-area: A2;
    gap: 0;
    width: 100%;
    height: 100%;
    background: #D3D1E5;
    border-radius: 15px;
    box-shadow: 0 0.3em #8E8CB6;
    align-items: center;
    justify-items: center;
}
.Act-list2 > div:last-child {
    grid-area: A3;
}
.Act-list-img {
    grid-row: 1 / 3;
    margin: 5px 10px;
}
.Act-description {
    font-size: 130%;
    font-weight: bold;
    justify-self: left;
}
.Act-progress-bar {
    position: relative;
    grid-row: 2 / 3;
    width: 50%;
    height: 12px;
    background-color: #000;
    border-radius: 15px;
    margin: 5px 0;
    font-size: 170%;
    color: white;
    line-height: 10px;
    font-weight: bold;
    text-align: center;
    justify-self: left;
}
.Act-progress-bar > div {
    display: block;
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    background-color: #FFBB33;
    border: 1px solid #000;
    border-radius: 15px;
}
.Act-progress-bar > div > div {
    position: relative;
    top: 3px;
    text-shadow: 1px -1px black, -1px -1px black, 1px 1px black, -1px 1px black;
}
.Act-dp-icon {
    display: grid;
    grid-row: 1 / 3;
    width: 85%;
    height: 75%;
    border-radius: 15px;
    color: #fff;
    font-size: 120%;
    font-weight: bold;
    text-align: center;
    align-items: center;
}

.Act-list::-webkit-scrollbar {
    width: 7px;
    background: #8F978D;
    border-radius: 15px;
}
.Act-list::-webkit-scrollbar-thumb {
    background: #5C5F63;
    border-radius: 15px;
}

