@media screen and (max-width:768px){
.BattlePassButton {
  display: grid;
  grid-template-columns: repeat(1, 1fr);  
  gap: 18px;                              
  padding: 0;
}
}

@media screen and (min-width:769px){
.BattlePassButton {
  display: grid;
  grid-template-columns: repeat(2, 1fr);  
  gap: 18px;                              
  padding: 0;
}
}

.BattlePassButton > div {
  position: relative;
  border-radius: 12px;      
  overflow: hidden;        
  background-color: transparent !important;
}
.BattlePassButton > div h3 {
  margin: 0;                
  width: auto;
  height: 145px;            
  background-color: transparent ;       
  background-size: cover;
  background-position: center;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 16px;
  text-shadow: 1px 1px 2px black;
}
/* 通行证名称 */
.BattlePassName {
  position: absolute;
  top: 20%;
  left: 15%;
  z-index: 2;
  color: #fff;
  font-size: 28px;
  font-weight: bold;
  text-shadow: 3px 0 0 #000, 2.77px 1.15px 0 #000, 2.12px 2.12px 0 #000, 1.15px 2.77px 0 #000, 0 3px 0 #000, -1.15px 2.77px 0 #000, -2.12px 2.12px 0 #000, -2.77px 1.15px 0 #000, -3px 0 0 #000, -2.77px -1.15px 0 #000, -2.12px -2.12px 0 #000, -1.15px -2.77px 0 #000, 0 -3px 0 #000, 1.15px -2.77px 0 #000, 2.12px -2.12px 0 #000, 2.77px -1.15px 0 #000;
  white-space: nowrap;
}
.BattlePassTime_img {
  position: absolute;
  bottom: 20%;
  left: 7%;
  z-index: 2;
}
.BattlePassTime_img img {
  display: block;
  width: auto; 
  height: auto;
  max-width: 100%;
}
.BattlePassTime-text {
  position: absolute;
  top: 50%;
  left: 23%;
  transform: translateY(-50%);
  color: #fff;
  font-size: 12px;
  font-weight: bold;
  white-space: nowrap;
  z-index: 3;
}
/*第一期额外需要图*/
.BattlePass_1 {
  position: absolute;
  top: 1.2%;
  left: 3.7%;
  z-index: 2;
}
.BattlePass_1 img {
  display: block;
  width: 70px; 
  height: 70px;
}
