.ClearPass{
    display: relative;
    width: 100%;
    overflow-x: auto;
}

.show_award{
    display: flex;
    width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}
.level_award{
    display: flex;
    flex-shrink: 0;
    justify-content: center;
    margin-left: 1%;
    margin-right: 1%;
}
.level_award center {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
}
.level_award .award {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 60px;
    width: 100%;
    margin: 12px 0;
}
.level_award .level {
    color: white;
    background-color: black;
    width: 32px;
    height: 32px;
    line-height: 32px;
    text-align: center;
    border-radius: 50%;
    margin: 15px 0;
    position: relative;
    z-index: 1; 
}
/* ====== 魔法连线部分 ====== */
.level_award .level::before {
    content: "";
    position: absolute;
    top: 50%;
    /*让线条从圆圈的“最左边缘”开始，完全不进入圆内 */
    right: calc(100% - 1px);
    width: 73px; 
    height: 10px;
    background-color: black;
    transform: translateY(-50%);
}

/* 关闭第一个圆点的向左连线 */
.level_award:first-child .level::before {
    display: none;
}
}}

