    height: 60% !important;  
    object-fit: contain;
    z-index: 1;
}  z-index: 1;
}
.reward-cell-inner .reward-img {
    width: 4px !important;
    height: auto !important;
    max-width: 1px !important;   
    max-height: none !important; 
    position: relative;
    z-index: 2;
    display: block;
    margin: auto;
}



<!-- /* 数量角标：右下角小胶囊，半透明黑底白字，位于最上层且不响应鼠标 */ -->
