.Act-list {
    display: flex;
    flex-direction: column;
    font-family:'荆南波波黑';
    height: 60%;
    padding: 10px;
    gap: 10px;
    overflow: auto;
}
.Act-list2 {
    display: grid;
    grid-template-columns: 6fr 1fr;
    grid-template-rows: 1fr;
    grid-template-areas: "A2 A3";
    gap: 0;
    width: 100%;
    height: 100%;
    align-items: center;
    justify-items: center;
}
.Act-list2 > div:first-child {
    display: grid;
    grid-template-columns: 1fr 4fr 2fr;
    grid-template-rows: 1fr 1fr;
    grid-area: A2;
    gap: 0;
    width: 100%;
    height: 100%;
    background: #B9F2FF;
    border-radius: 15px;
    box-shadow: 0 0.3em #48E0FF;
    align-items: center;
    justify-items: center;
}
.Act-list2 > div:last-child {
    grid-area: A3;
}
.Act-list-img {
    grid-row: 1 / 3;
    margin: 5px 10px;
}
.Act-description {
    font-size: 130%;
    font-weight: bold;
    justify-self: left;
}
.Act-progress-bar {
    position: relative;
    grid-row: 2 / 3;
    width: 50%;
    height: 12px;
    background-color: #000;
    border-radius: 15px;
    margin: 5px 0;
    font-size: 170%;
    color: white;
    line-height: 10px;
    font-weight: bold;
    text-align: center;
    justify-self: left;
}
.Act-progress-bar > div {
    display: block;
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    background-color: #87ECC8;
    border: 1px solid #000;
    border-radius: 15px;
}
.Act-progress-bar > div > div {
    position: relative;
    top: 3px;
    text-shadow: 1px -1px black, -1px -1px black, 1px 1px black, -1px 1px black;
}
.Act-dp-icon {
    display: grid;
    grid-row: 1 / 3;
    width: 85%;
    height: 75%;
    border-radius: 15px;
    color: #fff;
    font-size: 120%;
    font-weight: bold;
    text-align: center;
    align-items: center;
}

.Act-list::-webkit-scrollbar {
    width: 7px;
    background: #8F978D;
    border-radius: 15px;
}
.Act-list::-webkit-scrollbar-thumb {
    background: #5C5F63;
    border-radius: 15px;
}
.Act-check-icon{display:none;}
}}
